            raise FloatingPointError(
                "non-finite value encountered during mean squared log error"
            )
        error_terms.append(term)

    try:
        total_error = math.fsum(error_terms)
    except (OverflowError, ValueError) as exc:

    except (OverflowError, ValueError) as exc:
        raise FloatingPointError(
            "non-finite value encountered during mean squared log error"
        ) from exc
