        raise FloatingPointError(
            "non-finite value encountered during mean squared log error"
        )
    try:
        result = total_error / total_weight
    except (OverflowError, ValueError, ZeroDivisionError) as exc:
        raise FloatingPointError(
            "non-finite value encountered during mean squared log error"
        ) from exc
    if not math.isfinite(result):
        raise FloatingPointError(
            "non-finite value encountered during mean squared log error"
        )
    if result == 0:
        result = 0.0
    return result


