            finite = math.isfinite(value)
        except OverflowError as exc:
            raise ValueError(
                "y_pred must contain only finite strictly positive "
                "non-boolean numbers"
            ) from exc
        if not finite or value <= 0:
            raise ValueError(
                "y_pred must contain only finite strictly positive "
                "non-boolean numbers"
